module nortl_delay(CLK_I, RST_ASYNC_I, IN, OUT, CLK_REQ);
  input CLK_I;
  wire CLK_I;
  input RST_ASYNC_I;
  wire RST_ASYNC_I;
  input [0:0] IN;
  wire [0:0] IN;
  output [0:0] OUT;
  wire [0:0] OUT;
  output CLK_REQ;
  wire CLK_REQ;
  wire _0_;
  wire _1_;
  reg [0:0] \shiftreg[0] ;
  reg [0:0] \shiftreg[1] ;
  assign _0_ = \shiftreg[1]  | \shiftreg[0] ;
  assign _1_ = ~(\shiftreg[1]  & \shiftreg[0] );
  assign CLK_REQ = IN ? _1_ : _0_;
  always @(posedge CLK_I, posedge RST_ASYNC_I)
    if (RST_ASYNC_I) \shiftreg[0]  <= 1'h0;
    else \shiftreg[0]  <= IN;
  always @(posedge CLK_I, posedge RST_ASYNC_I)
    if (RST_ASYNC_I) \shiftreg[1]  <= 1'h0;
    else \shiftreg[1]  <= \shiftreg[0] ;
  assign OUT = \shiftreg[1] ;
endmodule

module nortl_edge_detector(CLK_I, RST_ASYNC_I, SIGNAL, RISING, FALLING, CLK_REQ);
  input CLK_I;
  wire CLK_I;
  input RST_ASYNC_I;
  wire RST_ASYNC_I;
  input SIGNAL;
  wire SIGNAL;
  output RISING;
  wire RISING;
  output FALLING;
  wire FALLING;
  output CLK_REQ;
  wire CLK_REQ;
  wire _0_;
  wire _1_;
  reg [1:0] sr;
  assign FALLING = sr[1] & ~(sr[0]);
  assign _0_ = sr[1] | sr[0];
  assign _1_ = ~(sr[1] & sr[0]);
  assign CLK_REQ = SIGNAL ? _1_ : _0_;
  assign RISING = sr[0] & ~(sr[1]);
  always @(posedge CLK_I, posedge RST_ASYNC_I)
    if (RST_ASYNC_I) sr[0] <= 1'h0;
    else sr[0] <= SIGNAL;
  always @(posedge CLK_I, posedge RST_ASYNC_I)
    if (RST_ASYNC_I) sr[1] <= 1'h0;
    else sr[1] <= sr[0];
endmodule

module nortl_sync(CLK_I, RST_ASYNC_I, IN, OUT, CLK_REQ);
  input CLK_I;
  wire CLK_I;
  input RST_ASYNC_I;
  wire RST_ASYNC_I;
  input [0:0] IN;
  wire [0:0] IN;
  output [0:0] OUT;
  reg [0:0] OUT;
  output CLK_REQ;
  wire CLK_REQ;
  assign CLK_REQ = OUT ^ IN;
  always @(posedge CLK_I, posedge RST_ASYNC_I)
    if (RST_ASYNC_I) OUT <= 1'h0;
    else OUT <= IN;
endmodule
